INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('69996473-6474-4890-a26c-e7cae3f62784', '21feff02-016d-46e2-bb9d-c27495133b1b', '30. óra: Szorzás törttel, a reciprok', 'Tört szorzása törttel, reciprok fogalma.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "cc0c1fa5-be10-48cb-87ff-84672bcdd0f6", "text": "Hogyan szorzunk törttel törtet?", "type": "multiple-choice", "options": [{"id": "13c20b56-eba8-4a9c-b412-b7493f3b8366", "text": "A számlálót a számlálóval, a nevezőt a nevezővel szorozzuk", "isCorrect": true}, {"id": "e50e5975-001d-4001-9b87-296ecd858273", "text": "Közös nevezőre hozzuk őket", "isCorrect": false}, {"id": "cc02fda8-14e5-49ee-b007-d3f2d7063712", "text": "A számlálót a nevezővel szorozzuk", "isCorrect": false}, {"id": "75fd31a2-968b-46e7-b97a-ce03272c3604", "text": "Keresztbe szorzunk", "isCorrect": false}], "timeLimit": 15}, {"id": "fd62e583-cb01-4cd8-9d37-a0ed11cccd13", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "859d5c09-62b9-4f7f-ab07-29121be01f25", "text": "6/15 (azaz 2/5)", "isCorrect": true}, {"id": "b5c70bbe-a1bd-4ccf-9bc3-581b8cdf3a29", "text": "5/8", "isCorrect": false}, {"id": "81220785-2e8b-4947-b792-76d422d45334", "text": "6/8", "isCorrect": false}, {"id": "3e7687ad-adb7-44ca-828f-4bb00a2d3a41", "text": "2/15", "isCorrect": false}], "timeLimit": 15}, {"id": "62e7fa2a-1ffa-4d13-836b-7a3f2a740f77", "text": "Mi a 3/4 reciproka?", "type": "multiple-choice", "options": [{"id": "3f7fff84-d71e-4fd8-a9eb-6bb40e124ec7", "text": "4/3", "isCorrect": true}, {"id": "2a598af6-9d6a-4ca2-951e-abc1f2e7cd9f", "text": "-3/4", "isCorrect": false}, {"id": "1384e5f6-03de-43e6-af7a-feac01eada28", "text": "1/4", "isCorrect": false}, {"id": "fd638889-152b-42e7-968c-5e3c53c9df6c", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "fe1b1062-7af6-4e4b-8d73-e8abc15a6780", "text": "Egy szám és a reciproka szorzata mindig 1.", "type": "true-false", "options": [{"id": "c8300eba-c14f-427f-8457-3c0c2473d7d5", "text": "Igaz", "isCorrect": true}, {"id": "3d934967-25b8-4527-b1a6-6d3f1d4d5738", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "df9b3c03-022f-4895-b567-9e9eb36bc781", "text": "Mi a 5 egész reciproka?", "type": "multiple-choice", "options": [{"id": "ebd3331d-2f15-4dc5-971e-67e6608583a1", "text": "1/5", "isCorrect": true}, {"id": "a1731f50-abc7-4345-a67d-95ba2ed0e557", "text": "-5", "isCorrect": false}, {"id": "c2c05764-6778-4717-916c-7ba182df06a1", "text": "5/1", "isCorrect": false}, {"id": "3711afbe-4f45-4f0b-a0bb-7c15d9e6fd5c", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "35c823f8-04cf-442d-b4e1-5c073cf38168", "text": "A 0-nak nincs reciproka.", "type": "true-false", "options": [{"id": "aa1634bf-e254-4dbb-90b2-aa4beede12ee", "text": "Igaz", "isCorrect": true}, {"id": "8d18a5f6-0481-4a15-ae05-c9f49c534e24", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5bf3aa3b-ba59-4042-85a9-5e0d6f6c5f30", "text": "Mennyi 1/2 * 1/3?", "type": "multiple-choice", "options": [{"id": "94beac25-1dc0-441a-b9e7-fb07693bf28f", "text": "1/6", "isCorrect": true}, {"id": "ed681fbd-c9ab-46f3-a726-cd0269882fe4", "text": "2/5", "isCorrect": false}, {"id": "8f625a52-85ca-4a6e-8eeb-6274bf9d6248", "text": "1/5", "isCorrect": false}, {"id": "e62b99a2-1a58-4ee1-a9c9-b78c7a4c6986", "text": "2/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e446f30b-172b-449c-9aa1-1ee4560c9558', '21feff02-016d-46e2-bb9d-c27495133b1b', '31. óra: A törtek szorzását alkalmazó feladatok megoldása', 'Törtrész kiszámítása és szöveges feladatok megoldása szorzással.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "613f2c3a-dd81-4b9c-b641-f5e0974db8f8", "text": "Mennyi 60-nak a 3/4 része? (60 * 3/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "e5e34e45-19df-42a8-accb-cc8f825ff5c9", "text": "Mennyi 100-nak az 1/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "bb3af801-8b8a-4a4d-a159-bd7dca2e2c99", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szeletet ettek meg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "4d9eba3e-e974-4cc4-9492-e08a92942206", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szelet maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "a0c09205-f094-4707-bb77-1d7464f01712", "text": "Egy szám törtrészének kiszámításához a számot megszorozzuk a törttel.", "type": "true-false", "options": [{"id": "45e995fb-56a6-44ef-acfe-94901a432c14", "text": "Igaz", "isCorrect": true}, {"id": "d87d02e8-7714-4a53-8947-c0c9d14e5ab1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "996e2bdf-4a11-41fa-b353-3e6c076df399", "text": "Mennyi 50-nek a 2/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "4cf3d259-129b-4cc1-9482-6737eb0b46f6", "text": "Mennyi 1/2 óra percekben? (60 * 1/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a99e6786-8cb6-4344-8ae4-41c5f817f548', '21feff02-016d-46e2-bb9d-c27495133b1b', '32. óra: Osztás törttel', 'Törttel való osztás szabálya: szorzás a reciprokával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "871b1f3c-1fe3-47c9-8bce-f1a24c2813d7", "text": "Hogyan osztunk törttel?", "type": "multiple-choice", "options": [{"id": "472d415e-e6bd-4f8a-9d5b-8c76517dfd9c", "text": "Az osztandót megszorozzuk az osztó reciprokával", "isCorrect": true}, {"id": "ebd09001-955b-4ab2-9944-5eaea6c7c385", "text": "Az osztandót elosztjuk a nevezővel", "isCorrect": false}, {"id": "59887ed7-90bb-4fce-94fd-f9cabb1fbe36", "text": "Mindig 1-et kapunk", "isCorrect": false}, {"id": "f5f00447-30c2-4c58-bcdf-844aa8bb8b0f", "text": "A számlálókat elosztjuk egymással", "isCorrect": false}], "timeLimit": 15}, {"id": "a86bfefb-2e39-4058-9662-027ff25dc321", "text": "Mennyi 2/3 : 4/5? (2/3 * 5/4)", "type": "multiple-choice", "options": [{"id": "5ed463a4-ff1b-4c35-b27d-6b32b9262f03", "text": "10/12 (azaz 5/6)", "isCorrect": true}, {"id": "29b05d79-baa5-48e9-9954-aba9c021dd3f", "text": "8/15", "isCorrect": false}, {"id": "5b17cd89-45d4-4b6a-b0c6-14633cfdddf5", "text": "6/8", "isCorrect": false}, {"id": "600cc0c5-3242-4f84-a791-f3e1b160f369", "text": "15/8", "isCorrect": false}], "timeLimit": 15}, {"id": "5d262335-cbeb-4095-88d9-759d39b2051b", "text": "Mennyi 1/2 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "26ce8c06-1ab2-444c-a715-cd8a0a753440", "text": "Ha egy számot 1/2-del osztunk, az eredmény megegyezik a szám 2-vel való szorzatával.", "type": "true-false", "options": [{"id": "eb4c53c5-2a6b-43af-aad0-3a45ac462b20", "text": "Igaz ( : 1/2 = * 2)", "isCorrect": true}, {"id": "23f6d9b7-a561-4b18-bca2-8224e6e68800", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dd215f39-0599-4e36-9296-32ff83f70cd4", "text": "Mennyi 6 : 1/3? (6 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "d9d60cbd-5eb6-4a47-9f10-4d5ebbd98c98", "text": "Törttel való osztáskor az osztandó nem változik, csak az osztót fordítjuk meg.", "type": "true-false", "options": [{"id": "7a7b25bf-b5c4-43d5-b07a-16c0d34dabf9", "text": "Igaz", "isCorrect": true}, {"id": "ddcc65e4-328f-425a-8b54-a8b5fb4e1dc9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b97de811-f09a-4d1b-b2e8-7e29d838afcd", "text": "Mennyi 3/4 : 3/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('02986052-2926-40d2-ac07-0971566f4e60', '21feff02-016d-46e2-bb9d-c27495133b1b', '33. óra: Hétköznapi problémák megoldása törtek osztásának felhasználásával', 'Szöveges feladatok mérésekkel, átdarabolásokkal, törtek osztásával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "0886c330-f51f-4031-9b99-332178a0ead5", "text": "Hány 1/4 literes pohár tölthető meg 3 liter almaléből? (3 : 1/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "fc807549-efe8-4834-9ce4-446c296a7613", "text": "Hány 1/2 kg-os csomag képezhető 5 kg cukorból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "0e17a318-8df9-41ad-99bf-0a39b6cd7fc1", "text": "Egy 6 méteres szalagból 3/4 méteres darabokat vágunk. Hány darabot kapunk? (6 : 3/4 = 6 * 4/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "5168580d-d365-43af-95d4-7f820f269bf7", "text": "Törtek osztásakor az eredmény lehet nagyobb az eredeti osztandónál, ha az osztó 1-nél kisebb tört.", "type": "true-false", "options": [{"id": "5ebdd7aa-e931-4354-a38a-b40ef95af462", "text": "Igaz", "isCorrect": true}, {"id": "7998b754-ca53-4bf0-82a2-efd97682222e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "07fccf8a-0096-42cc-b7b9-f13265df961d", "text": "Hány 1/5 méteres darab vágható ki 2 méter anyagból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "5c68c345-419b-423a-869f-0ffdf969a625", "text": "A szöveges feladatoknál az adatok lejegyzése és a mértékegységek egyeztetése elengedhetetlen.", "type": "true-false", "options": [{"id": "10ee890c-87fa-4434-9f06-50834a4940b5", "text": "Igaz", "isCorrect": true}, {"id": "379b92cd-775f-45b1-9843-299908bba53a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8075fded-04e9-4ae5-bbff-7057313d50ea", "text": "Mennyi 4 : 2/3? (4 * 3/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('552a3d87-acf8-4d1c-a756-ef1697800e65', '21feff02-016d-46e2-bb9d-c27495133b1b', '34. óra: Gyakorlóóra', 'A törtek szorzásának és osztásának rögzítése, feladatok gyakorlása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "8f4919ac-d359-4c19-aef7-e121decc6377", "text": "Mennyi 3/5 * 5/3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "d54a93af-ce49-4824-bd6c-a3ca17340c7c", "text": "Mennyi 4/7 : 2/7? (4/7 * 7/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "4f7b5ad3-279c-45ca-8731-05fdf74cc02b", "text": "Melyik állítás igaz?", "type": "multiple-choice", "options": [{"id": "2346eada-d46c-49b3-a916-6215ed9c9143", "text": "Két 1-nél kisebb pozitív tört szorzata kisebb mindkét tényezőnél", "isCorrect": true}, {"id": "539e5f77-2a87-45d5-bc2f-019a281abe39", "text": "A szorzat mindig nagyobb a tényezőknél", "isCorrect": false}, {"id": "90dbb2bd-6a7c-4d29-83a2-cd97b25facfc", "text": "Az osztás mindig kisebb számot ad", "isCorrect": false}, {"id": "6be32f16-f7c5-4039-9e5d-5aaf44c782c0", "text": "Nincs reciproka a 4/5-nek", "isCorrect": false}], "timeLimit": 15}, {"id": "e4da4423-b441-48c1-90c7-1a0322f1143f", "text": "Mennyi 5/6 * 12? (5 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "25712e5d-5377-4b10-8980-2d67d33be673", "text": "A 2/3 osztva 1/3-dal 2-t ad.", "type": "true-false", "options": [{"id": "1a799eef-2287-47d1-98d5-9a02df378dc1", "text": "Igaz", "isCorrect": true}, {"id": "8620ed37-f572-43db-8e47-505bb834b520", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "157f751e-8c28-493d-b12d-32524d0c3ec9", "text": "Mennyi 3/8 : 3/8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "abfeb1e1-404a-4be4-8a67-e8eb89c9fd2d", "text": "Mennyi 1/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "6b02bd48-d4ae-436a-b10f-2e9c463f7855", "text": "1/5", "isCorrect": true}, {"id": "991d3947-3917-4a94-949f-097193448240", "text": "4/20", "isCorrect": false}, {"id": "12118afd-e32a-4542-a5b6-b58a0e4e7e35", "text": "1/20", "isCorrect": false}, {"id": "64cd5150-1543-422c-b973-4394aeabe7ba", "text": "4/9", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7ad6c97a-c5d0-4b9f-b34e-cdd1839a6279', '21feff02-016d-46e2-bb9d-c27495133b1b', '35. óra: Számonkérés', 'Számonkérés a közönséges törtek műveleteiből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "5a2f4638-2516-426e-9729-df5cf803d622", "text": "1. Mennyi 2/5 + 1/5?", "type": "multiple-choice", "options": [{"id": "6948dee9-dfba-49a7-9c09-ec688f50008d", "text": "3/5", "isCorrect": true}, {"id": "8b00fec7-45bb-4eab-b094-c9a3bf4df6dd", "text": "3/10", "isCorrect": false}, {"id": "7dcaa067-a586-4f0b-8e45-bb1e02a1413a", "text": "2/10", "isCorrect": false}, {"id": "608f9e2d-38b1-4de7-a155-72589f6ac8e4", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "4e6bdb91-42b8-4880-a27a-3e6fa2ce18c6", "text": "2. Mennyi 3/4 - 1/2? (3/4 - 2/4)", "type": "multiple-choice", "options": [{"id": "3e834ec3-b4ec-49b2-bb77-2d8b047a704e", "text": "1/4", "isCorrect": true}, {"id": "0257be15-9721-438a-a5ab-2c4aa8aa1716", "text": "2/2", "isCorrect": false}, {"id": "b1e4ae1b-363a-4458-91d3-332e9332daeb", "text": "1/2", "isCorrect": false}, {"id": "c98c34f0-021c-492f-a46a-275cc9d847fb", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "3b49290a-a455-4328-90bd-0a84752200db", "text": "3. Mennyi 2/3 * 3/4?", "type": "multiple-choice", "options": [{"id": "2e8894b2-3386-4302-be86-2f7045b2ad8e", "text": "6/12 (azaz 1/2)", "isCorrect": true}, {"id": "123ad4f2-6b29-4151-b3ad-8cea63b5041c", "text": "5/7", "isCorrect": false}, {"id": "67147c3c-985a-4aa7-ba32-01d4d7537bdf", "text": "6/7", "isCorrect": false}, {"id": "b95cb933-b178-4d45-946c-e55efd1e28a7", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "eb7156bf-01fb-4a2b-9227-a03e25413027", "text": "4. Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "6a46a98a-5a6c-411c-ba93-83bf078be1c3", "text": "5. Mi a 7/8 reciproka?", "type": "multiple-choice", "options": [{"id": "22bd4113-ee3d-4dd2-a42c-298c01361332", "text": "8/7", "isCorrect": true}, {"id": "4624a66a-014f-4a4e-81e9-f98e6771225f", "text": "-7/8", "isCorrect": false}, {"id": "446ecbcb-6f18-4df6-a39e-d18d6b30932b", "text": "1/7", "isCorrect": false}, {"id": "cf2b0d53-1777-45c4-b6cf-3d15945b5bcd", "text": "7/8", "isCorrect": false}], "timeLimit": 15}, {"id": "7eadda4f-dfd5-420e-9874-22aa87c173b7", "text": "6. Mennyi 40-nek a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "b4e3eee8-1562-43e6-8d30-742349bfd9f8", "text": "7. Egy szám és reciproka szorzata 1.", "type": "true-false", "options": [{"id": "44fda263-f6a9-4f7d-afc3-55cb637deefc", "text": "Igaz", "isCorrect": true}, {"id": "ff3911f3-0b99-4cd0-b19a-6e1280031478", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cddfefe7-d888-4d34-9fa0-d4fd1cac5ade", "text": "8. Mennyi 5 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d4a22fac-7d65-4432-b080-96bb80bdc1c7", "text": "9. A törtek szorzásakor a számlálót a számlálóval, a nevezőt a nevezővel szorozzuk.", "type": "true-false", "options": [{"id": "2bf216f8-e146-4343-9986-7b19b19eaedf", "text": "Igaz", "isCorrect": true}, {"id": "9949f175-ac2d-4899-af80-bf2234710d01", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1b53aaa6-2e69-436d-980e-3494ca14aff2", "text": "10. Hány negyedből áll 3 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f2961343-267f-4be8-bff5-46e3209fece9', '21feff02-016d-46e2-bb9d-c27495133b1b', '36. óra: Matematikai játékok', 'Matematikai társasjátékok, stratégiák törtekkel, csoport- és páros munka.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "4c96db93-3c06-49b0-b175-477af85e9b82", "text": "Melyik állítás igaz a matematikai társasjátékokról?", "type": "multiple-choice", "options": [{"id": "3fd2335e-8261-4e16-b298-ad4f3e9c5559", "text": "Fejlesztik a számolási gyorsaságot és a logikai stratégiát", "isCorrect": true}, {"id": "ce2db145-e675-428a-a9a7-a600c00c1164", "text": "Nincs közük a matematikához", "isCorrect": false}, {"id": "7cf2742c-e170-47e7-ab76-007d6a70fddb", "text": "Kizárólag szerencse kell hozzájuk", "isCorrect": false}, {"id": "f28ddb22-3728-4fb0-9742-a5ff22178dd3", "text": "Tiltható az együttműködés", "isCorrect": false}], "timeLimit": 15}, {"id": "5fd210d0-6ef3-4b44-bd40-00972615f379", "text": "A tört domino játékban az egyenlő értékű törteket illesztjük össze.", "type": "true-false", "options": [{"id": "f103c802-173d-42d9-8476-ea2832d54581", "text": "Igaz", "isCorrect": true}, {"id": "6df1e808-3be8-4a16-9ceb-c0fe8b4ddb36", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5c752538-2345-4a29-bcac-0b89b18e37be", "text": "Melyik tört felel meg a 0,5 tizedes törtnek?", "type": "multiple-choice", "options": [{"id": "69cd66df-bd2e-46fb-ad91-0d6c8175a360", "text": "1/2", "isCorrect": true}, {"id": "ab2cf384-498d-4b5c-b2b3-b88e003b5b62", "text": "1/5", "isCorrect": false}, {"id": "1b42a804-3dc8-4b59-8c88-ab0152cdf1f6", "text": "2/5", "isCorrect": false}, {"id": "ca85d5ae-0a6c-4037-8607-75351be99c91", "text": "5/2", "isCorrect": false}], "timeLimit": 15}, {"id": "49e4100b-26f8-4cf4-9cae-3ef4a4d43c05", "text": "Melyik tört felel meg a 0,25-nek?", "type": "multiple-choice", "options": [{"id": "c3b6cc52-1489-4bb6-ad06-c305fd9a0c44", "text": "1/4", "isCorrect": true}, {"id": "6e3fc535-0f8d-4241-8ddb-2445f6f0a1b3", "text": "1/2", "isCorrect": false}, {"id": "d92ffddc-bf00-41d0-b02d-e366906fbebc", "text": "2/5", "isCorrect": false}, {"id": "142bc2b7-1e91-475a-a485-75e369a84674", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "ddf825b1-6303-46d2-81a1-e3f8f2a92a16", "text": "A 3/4 tizedes tört alakja 0,75.", "type": "true-false", "options": [{"id": "058f44e6-65c9-4d51-995a-75774848306d", "text": "Igaz", "isCorrect": true}, {"id": "d8a5c6c4-ef65-47a8-afbe-0514fa51cce1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7b56089f-3c74-4678-ad07-443504f41332", "text": "Mennyi 0,2 közönséges tört alakban legegyszerűbb formában?", "type": "multiple-choice", "options": [{"id": "7e3631c5-22aa-4ec8-98d6-3da569b09241", "text": "1/5", "isCorrect": true}, {"id": "8b7e4a1c-2112-4cde-95a9-b84573258d5a", "text": "2/10", "isCorrect": false}, {"id": "153ccf85-3c4d-4896-95bf-2d9103d63d5d", "text": "1/2", "isCorrect": false}, {"id": "a7dba829-0cf2-478b-9352-a432a9fe31c7", "text": "2/5", "isCorrect": false}], "timeLimit": 15}, {"id": "3852d313-e751-4b23-b079-736fe2faafb9", "text": "A tört-bingó játékban a válaszok gyors és pontos kiszámítása a nyerő stratégia.", "type": "true-false", "options": [{"id": "f6e58607-9ca1-4164-8612-b3d6fcb1fdad", "text": "Igaz", "isCorrect": true}, {"id": "812a1d77-4704-4475-9e3d-2305df31ae02", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4053c41e-bf80-44ce-b14a-548fd400bc4b', '21feff02-016d-46e2-bb9d-c27495133b1b', '37. óra: Mit tanultunk a tizedes törtekről?', 'Tizedes törtek helyi értékei, összeadása és kivonása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "8f33e3d6-121a-424d-b812-3281e3aeb536", "text": "Mi a tizedesvessző utáni első helyi érték neve?", "type": "multiple-choice", "options": [{"id": "61b50181-dd9e-44ac-bae1-51b4c39fd99d", "text": "Tizedek", "isCorrect": true}, {"id": "cc2819eb-7a9e-45b2-aa51-5ef3a9376619", "text": "Századok", "isCorrect": false}, {"id": "1359d1c7-ed29-4956-b5fa-9b8cb534dd49", "text": "Ezredeket", "isCorrect": false}, {"id": "f4324ba6-14f0-4e2d-8686-82912cab2e7e", "text": "Egyesek", "isCorrect": false}], "timeLimit": 15}, {"id": "c8a6a171-0552-4aec-a93e-b02fb6ac2f49", "text": "Mi a tizedesvessző utáni második helyi érték neve?", "type": "multiple-choice", "options": [{"id": "18c6cd88-cc8d-433e-a4b4-68d6547ad724", "text": "Századok", "isCorrect": true}, {"id": "f05bfcc5-a6dc-459b-bbbb-34dcbbb938e2", "text": "Tizedek", "isCorrect": false}, {"id": "360fb9eb-7a08-4f47-a9d0-6f0e000af63d", "text": "Ezredek", "isCorrect": false}, {"id": "84075f19-b5e4-4bcf-9d38-5d422e8bfb40", "text": "Tízesek", "isCorrect": false}], "timeLimit": 15}, {"id": "4ba29a72-18de-4554-91f0-23466a6808fe", "text": "Mennyi 3,45 + 2,13?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5.58"}, {"id": "fdcb3e90-7e47-45f4-badc-58518d907399", "text": "Mennyi 7,8 - 3,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.3"}, {"id": "f2515538-fda6-4a64-bb99-bf59b25d1e5a", "text": "Tizedes törtek írásbeli összeadásakor a tizedesvesszőknek egymás alá kell kerülniük.", "type": "true-false", "options": [{"id": "69d03996-823b-4895-b3d7-92fd594c7b7b", "text": "Igaz", "isCorrect": true}, {"id": "cd051989-eb9b-464a-b95d-1bbdbeb613f4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ff5519c6-1e97-4d45-8fad-0bc09961c77f", "text": "Mennyi 5,6 + 4,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "9229c386-3315-4a11-bd7c-f180c04600c4", "text": "Melyik szám nagyobb: 4,05 vagy 4,5?", "type": "multiple-choice", "options": [{"id": "f43f3bd9-fa35-4820-80cf-0fb3ee414407", "text": "4,5 (mert 4,5 = 4,50)", "isCorrect": true}, {"id": "13743667-adea-4bfb-a84d-1c6815fb919a", "text": "4,05", "isCorrect": false}, {"id": "6a2f4c1c-7279-4227-9ca8-787755da49dd", "text": "Egyenlőek", "isCorrect": false}, {"id": "1225369b-949b-480a-a885-1633507d5114", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('94ecb101-5d2c-4a2c-b7c0-de60d67a5c27', '21feff02-016d-46e2-bb9d-c27495133b1b', '38. óra: Szorzás tizedes törttel', 'Tizedes tört szorzása egész számmal és tizedes törttel, vesszőhely meghatározása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "e4d92f00-9d5a-4dd1-b677-9b084984e4ca", "text": "Hogyan határozzuk meg a tizedesjegyek számát két tizedes tört szorzatában?", "type": "multiple-choice", "options": [{"id": "772912d6-1f21-4a27-85fb-a7d670a71009", "text": "A tényezők tizedesjegyeinek számát összeadjuk", "isCorrect": true}, {"id": "7072b3c8-bdde-424d-82a6-f88f03bb7905", "text": "A nagyobbik tényező tizedesjegyeit vesszük", "isCorrect": false}, {"id": "7e71ee75-7927-481e-9ae7-e171ce795abf", "text": "Mindig 1 tizedesjegy lesz", "isCorrect": false}, {"id": "a798752a-eefd-49b7-b50d-8532e97ac323", "text": "Nem lesz tizedesjegy", "isCorrect": false}], "timeLimit": 15}, {"id": "d0efa391-48a1-4ccd-b3d2-6b3b234fd62d", "text": "Mennyi 0,3 * 0,2? (3*2 = 6, 2 tizedesjegy)", "type": "multiple-choice", "options": [{"id": "c0d48d9c-7a24-43c7-9b12-0b0369411918", "text": "0,06", "isCorrect": true}, {"id": "3f234666-f1c1-42a2-b875-c79a25f61a8b", "text": "0,6", "isCorrect": false}, {"id": "b64c1868-0fe3-4cde-8e67-cb656261efd6", "text": "6,0", "isCorrect": false}, {"id": "012ba121-db54-4528-b1fe-a4b5e7cedadf", "text": "0,006", "isCorrect": false}], "timeLimit": 15}, {"id": "dd47127d-cbaa-4442-99ce-1578e4b988ac", "text": "Mennyi 2,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "10f0142c-8a10-47ec-aa0e-bcb71779ec6b", "text": "Mennyi 1,2 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "a091c571-e7ed-4a1b-b0b1-928ae23a99ca", "text": "Ha egy tizedes törtet 10-zel szorzunk, a tizedesvessző egy hellyel jobbra lép.", "type": "true-false", "options": [{"id": "1df69239-6d6d-42e8-977f-310a780b96aa", "text": "Igaz", "isCorrect": true}, {"id": "c73a23a5-b1b3-48c0-96a8-5e605bc3987d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cb2b2716-a75d-47e0-b3cf-25a599b1ecfc", "text": "Mennyi 3,45 * 100?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "345"}, {"id": "c057e644-1740-4f65-b35f-3fcf26f5ac00", "text": "Mennyi 0,1 * 0,1?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.01"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('38db9470-9ddb-48f9-a8ca-521b29d29d87', '21feff02-016d-46e2-bb9d-c27495133b1b', '39. óra: Osztás tizedes törttel', 'Tizedes törttel való osztás szabálya, osztó egész számmá alakítása (bővítés 10-zel, 100-zal).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "c5927e30-027c-4158-97e3-c892126cb7e1", "text": "Mit teszünk tizedes törttel való osztáskor először?", "type": "multiple-choice", "options": [{"id": "e8cd5d7b-5b5b-461d-a2e2-08ecf876088d", "text": "Az osztandót és az osztót is megszorozzuk 10-zel/100-zal, hogy az osztó egész szám legyen", "isCorrect": true}, {"id": "1dc1d140-c34c-40b2-900f-fed9b754ce02", "text": "Elhagyjuk a tizedesvesszőt az osztandóból", "isCorrect": false}, {"id": "013ca89d-8424-41ea-94ab-606a17cbac24", "text": "Kivonjuk az osztót az osztandóból", "isCorrect": false}, {"id": "4bdc6d04-bfe0-4029-86ea-d6dbe1727e53", "text": "Csak az osztót szorozzuk meg", "isCorrect": false}], "timeLimit": 15}, {"id": "eac2c7f4-f95f-4b85-87a4-ee9ca6fc6893", "text": "Mennyi 2,4 : 0,6? (24 : 6)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "46167006-209c-4c2f-927d-e7b8e18a6c6d", "text": "Mennyi 1,5 : 0,3? (15 : 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "a264ca05-cb8f-4ed4-8d19-673859ab8ade", "text": "Ha egy tizedes törtet 10-zel osztunk, a tizedesvessző 1 hellyel balra lép.", "type": "true-false", "options": [{"id": "59198265-4f57-44f5-9000-6a1024da993c", "text": "Igaz", "isCorrect": true}, {"id": "5bb85926-c007-4504-ab55-83e6b5a37c35", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9290e4f3-b6e5-42e5-be08-3fc9715b597a", "text": "Mennyi 45,6 : 10?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.56"}, {"id": "8608244c-9a2d-44b3-8cba-a715ce70fca4", "text": "Mennyi 3,6 : 0,1? (36 : 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "d3744b88-6060-44f3-b366-f6e2fbef531d", "text": "A tizedes törttel való osztást ellenőrizhetjük szorzással.", "type": "true-false", "options": [{"id": "27ee5020-e221-42a7-aed7-10ac56e12f86", "text": "Igaz", "isCorrect": true}, {"id": "fcfb91e2-9857-40b5-8e24-37339754e86e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());